create table outbox (id uuid primary key, event_id varchar(64) not null unique, aggregate_id varchar(64) not null, event_type varchar(64) not null, topic varchar(128) not null, partition_key varchar(128) not null, payload text not null, created_at timestamptz not null, published_at timestamptz); create index idx_outbox_unpublished on outbox (created_at) where published_at is null;
